  "tant;}\n  input,select,textarea,button{font-size:54px !important;}\n  .menu-btn b{font-size:57px !important;}\n  .menu-btn span{font-size:42px !important;}\n  .row{font-size:48px !important;}\n}\n</style>\n\n<style id=\"android-ui-final\">\n/* ANDROID MOBILE UI - CHỈ CSS, KHÔNG ĐỔI JS/API */\nhtml{font-size:16px!important;-webkit-text-size-adjust:100%;text-size-adjust:100%}\nbody{font-family:Roboto,Arial,sans-serif!important;background:#f3f6fa!important;min-height:100dvh;overflow-x:hidden!important}\nheader{padding:calc(12px + env(safe-area-inset-top)) 14px 12px!important;border-radius:0 0 16px 16px}\nheader h1{font-size:22px!important;line-height:1.15!important;margin:0 0 4px!important}\nheader small{font-size:14px!important}\nmain{width:100%!important;max-width:none!important;padding:10px!important;padding-bottom:calc(18px + env(safe-area-inset-bottom))!important}\n.card{padding:14px!important;margin-bottom:10px!important;border-radius:15px!important;box-shadow:0 2px 10px rgba(15,23,42,.07)!important}\nh2{font-size:21px!important;line-height:1.25!important}\nlabel{font-size:16px!important;line-height:1.4!important;margin:11px 0 6px!important}\ninput,select,textarea,button{width:100%!important;max-width:100%!important;min-height:50px!important;font-size:17px!important;line-height:1.25!important;border-radius:12px!important}\ninput,select,textarea{padding:12px 13px!important}\nbutton{padding:11px 13px!important;font-weight:700}\nbutton:active{transform:scale(.985)}\n.status{font-size:15px!important;line-height:1.45!important;padding:10px 12px!important}\n.menu-grid{display:grid!important;grid-template-columns:1fr 1fr!important;gap:9px!important}\n.menu-btn{min-height:78px!important;padding:11px 10px!important;border-radius:14px!important;text-align:left!important}\n.menu-btn b{display:block;font-s" +
  "ize:16px!important;line-height:1.2!important}\n.menu-btn span{display:block;margin-top:5px;font-size:12px!important;line-height:1.25!important}\n.sub{display:grid!important;grid-template-columns:1fr 1fr!important;gap:8px!important}\n.sub .back{grid-column:1/-1}\n.sub button{min-height:48px!important;font-size:15px!important}\n.return-connect-btn{min-height:54px!important;font-size:18px!important;margin-bottom:10px!important}\n.item{padding:11px!important;margin:8px 0!important;border-radius:12px!important}\n.item h3{font-size:17px!important}\n.row{font-size:14px!important;line-height:1.35!important;gap:8px!important}\n.row span:last-child{max-width:62%!important}\n.section-title{font-size:13px!important}\ndetails summary{font-size:15px!important;padding:11px!important}\n.feature-progress{padding:10px!important}\n.feature-progress .fp-head{font-size:13px!important}\n.feature-progress .fp-log{font-size:12px!important}\n.toast{left:10px!important;right:10px!important;bottom:calc(10px + env(safe-area-inset-bottom))!important;font-size:15px!important}\n.bulk-title{font-size:20px!important}\n.bulk-summary{font-size:15px!important}\n.bulk-table-wrap{overflow-x:auto!important;-webkit-overflow-scrolling:touch}\n.bulk-table{min-width:760px!important;font-size:14px!important}\n.bulk-table th,.bulk-table td{font-size:14px!important;padding:9px 10px!important}\n#panel,#panel>*,#bulkSearchArea,#bulkSearchArea>*{min-width:0!important;max-width:100%!important}\npre{max-width:100%!important;overflow:auto!important}\n@media(max-width:600px) and (orientation:portrait){.menu-grid{grid-template-columns:1fr!important}.menu-btn{min-height:68px!important}.menu-btn b{font-size:17px!important}.menu-btn span{font-size:13px!important}}\n@media(max-width:390px){main{padding:7px!important}.card{padding:11px!important}heade" +
  "r h1{font-size:20px!important}h2{font-size:19px!important}input,select,textarea,button{font-size:16px!important;min-height:48px!important}.menu-btn{min-height:64px!important;padding:9px 10px!important}.menu-btn b{font-size:16px!important}.menu-btn span{font-size:12px!important}.sub button{font-size:14px!important}}\n@media(max-width:900px) and (orientation:landscape){main{padding:8px 12px!important}.menu-grid{grid-template-columns:1fr 1fr!important}.menu-btn{min-height:66px!important}}\n</style>\n\n<style id=\"bulk-result-small-final\">\n/* KẾT QUẢ NHIỀU SERIAL: chữ nhỏ, hiển thị được nhiều chi tiết */\n#bulkSearchArea .bulk-title{font-size:16px !important;line-height:1.25 !important}\n#bulkSearchArea .bulk-summary{font-size:13px !important;line-height:1.3 !important;padding:8px 10px !important}\n#bulkSearchArea .bulk-table{font-size:12px !important;line-height:1.25 !important}\n#bulkSearchArea .bulk-table th,#bulkSearchArea .bulk-table td{font-size:12px !important;line-height:1.25 !important;padding:6px 7px !important}\n#bulkSearchArea .bulk-table th{font-weight:700 !important}\n#bulkSearchArea .bulk-ok,#bulkSearchArea .bulk-err{font-size:12px !important;line-height:1.25 !important}\n@media(max-width:600px){#bulkSearchArea .bulk-title{font-size:16px !important}#bulkSearchArea .bulk-summary{font-size:13px !important}#bulkSearchArea .bulk-table,#bulkSearchArea .bulk-table th,#bulkSearchArea .bulk-table td,#bulkSearchArea .bulk-ok,#bulkSearchArea .bulk-err{font-size:12px !important}}\n</style>\n</head>\n<body>\n\n<main>\n<div style=\"font-size:20px;font-weight:700;margin:0 0 12px\">MODEM REMOTE</div>\n<a href=\"/\" style=\"display:block;width:100%;box-sizing:border-box;margin:0 0 12px;padding:14px 16px;border-radius:12px;background:#3478f6;color:#fff;text-align:center;text-decoration:none;font-siz" +
  "e:18px;font-weight:700\">☰ Menu</a>\n<button id=\"logoutBtn\" onclick=\"logout()\" class=\"hidden\" title=\"Đăng xuất\" style=\"margin:0 0 12px;background:#dc2626;width:auto;padding:8px 14px;\">🚪Đăng xuất</button>\n<section id=\"authCard\" class=\"card\">\n<h2>Đăng nhập</h2>\n<label>Username</label>\n<input id=\"username\" autocomplete=\"username\" placeholder=\"Username\">\n<label>Password</label>\n<input id=\"password\" type=\"password\" autocomplete=\"current-password\" placeholder=\"Password\">\n<button onclick=\"loginStep1()\">Đăng nhập / Gửi OTP</button>\n<div id=\"authOtpBox\" class=\"hidden\">\n  <label>OTP</label>\n  <input id=\"otp\" inputmode=\"numeric\" placeholder=\"Nhập OTP\">\n  <button onclick=\"loginStep2()\">Xác thực OTP</button>\n</div>\n<div id=\"authStatus\" class=\"status\">Chưa đăng nhập.</div>\n<pre id=\"authResult\" class=\"hidden\">Chưa có dữ liệu.</pre>\n</section>\n\n<section id=\"login\" class=\"card\">\n  <div class=\"single-connect-head\">\n    <div class=\"single-connect-icon\">📡</div>\n    <div>\n      <h2>Kết nối modem</h2>\n    </div>\n  </div>\n\n  <label> <b>💡Nhập 1 Serial</b> → Cấu hình modem<br><b>💡Nhập nhiều Serial (;)</b> → Tìm MenID + PPPoE</label>\n  <input type=\"text\" id=\"serial\" spellcheck=\"false\" autocomplete=\"on\"\n    placeholder=\"VNPTxxxxxxx1;VNPTxxxxxx2\">\n\n  <button id=\"serialActionBtn\" onclick=\"handleSerialInput()\">KẾT NỐI / TÌM SERIAL</button>\n  \n  <div id=\"connectProgress\" class=\"feature-progress hidden\">\n    <div class=\"fp-head\">\n      <span id=\"cpText\">⏳ Đang kết nối...</span>\n      <span id=\"cpPercent\">0%</span>\n    </div>\n    <div class=\"fp-track\">\n      <div id=\"cpBar\" class=\"fp-bar\"></div>\n    </div>\n    <div id=\"cpLog\" class=\"fp-log\"></div>\n  </div>\n\n  <div id=\"bulkSearchArea\" class=\"hidden\">\n    <div class=\"bulk-title\">🔎 Kết quả tìm Serial / menID / PPPoE / Vật tư</div>\n\n    <div id=\"bulkPro" +
  "gress\" class=\"feature-progress hidden\">\n      <div class=\"fp-head\">\n        <span id=\"bulkProgressText\">Đang xử lý...</span>\n        <span id=\"bulkProgressPercent\">0%</span>\n      </div>\n      <div class=\"fp-track\">\n        <div id=\"bulkProgressBar\" class=\"fp-bar\"></div>\n      </div>\n      <div id=\"bulkProgressLog\" class=\"fp-log\"></div>\n    </div>\n\n    <div id=\"bulkSummary\"></div>\n    <div id=\"bulkResult\"></div>\n\n    <button type=\"button\" class=\"secondary\" onclick=\"clearBulkResult()\">XÓA KẾT QUẢ</button>\n  </div>\n</section>\n\n<section id=\"home\" class=\"hidden\">\n<div class=\"card\">\n<button type=\"button\" class=\"return-connect-btn\" onclick=\"backToConnection()\">⬅️ QUAY LẠI</button>\n<div id=\"status\" class=\"status\">Sẵn sàng</div>\n\n  <div id=\"progressLog\" class=\"progress-log\"></div>\n</div>\n<div class=\"menu-grid\">\n<button class=\"menu-btn\" onclick=\"openSection('device')\"><b>1. DEVICE INFO / SLID</b><span>Xem thông tin modem</span></button>\n<button class=\"menu-btn\" onclick=\"openSection('wan')\"><b>2. WAN</b><span>Xem / tạo / sửa / xóa</span></button>\n<button class=\"menu-btn\" onclick=\"openSection('lan')\"><b>3. LAN</b><span>Xem / SET LAN</span></button>\n<button class=\"menu-btn\" onclick=\"openSection('wifi')\"><b>4. WIFI</b><span>Xem / SET 2.4G - 5G</span></button>\n<button class=\"menu-btn\" onclick=\"openSection('optical')\"><b>5. OPTICAL</b><span>Xem thông số quang</span></button>\n<button class=\"menu-btn\" onclick=\"openSection('ping')\"><b>6. PING DNS</b><span>Ping host</span></button>\n<button class=\"menu-btn\" onclick=\"openSection('topology')\"><b>7. TOPOLOGY</b><span>Xem sơ đồ / thiết bị kết nối</span></button>\n<button class=\"menu-btn\" onclick=\"openSection('password')\"><b>8. WEB LOGIN PASSWORD</b><span>Đổi mật khẩu admin</span></button>\n<button class=\"menu-btn\" onclick=\"openSection('reboot')\"" +
  "><b>9. REBOOT MODEM</b><span>Khởi động lại modem</span></button>\n<button class=\"menu-btn\" onclick=\"openSection('firmware')\"><b>10. UPDATE FIRMWARE</b><span>Xem phiên bản và cập nhật firmware</span></button>\n</div></div>\n</section>\n\n<section id=\"section\" class=\"hidden\">\n<div class=\"card\">\n<div class=\"sub\"><button class=\"back\" onclick=\"goHome()\">← MENU CẤU HÌNH MODEM</button><button onclick=\"showView()\">Xem cấu hình</button><button onclick=\"showSet()\">Sửa cấu hình</button></div>\n<div id=\"panel\"></div>\n</div>\n</section>\n</main>\n<div id=\"toast\" class=\"toast\"></div>\n\n\n\n<script type=\"text/javascript\">\n\nconst API_BASE = location.pathname.startsWith(\"/onelink\") ? \"/onelink\" : \"\";\nconst API_1 = API_BASE + \"/api/auth/step1\";\nconst API_2 = API_BASE + \"/api/auth/step2\";\nconst NGHIEM_THU_URL = API_BASE + \"/api/thicong/nghiemThuMayHong\";\nconst DEVICE_ID = \"54524c30658290a7\";\nconst MOBILE_ID = \"\";\nconst MENU_ID = 11250;\nconst APP_ID = \"1\";\nconst APP_VERSION = \"1.5.41.086\";\nconst TOKEN_KEY = \"onebss_token\";\n\nfunction setAuthStatus(msg) {\n  document.getElementById(\"authStatus\").textContent = msg;\n}\n\nfunction showResult(obj) {\n  document.getElementById(\"authResult\").textContent =\n    typeof obj === \"string\" ? obj : JSON.stringify(obj, null, 2);\n}\n\nfunction saveToken(data) {\n  localStorage.setItem(TOKEN_KEY, JSON.stringify(data));\n}\n\nfunction loadToken() {\n  try {\n    const raw = localStorage.getItem(TOKEN_KEY);\n    return raw ? JSON.parse(raw) : null;\n  } catch (e) {\n    return null;\n  }\n}\n\nfunction getValidToken() {\n  const t = loadToken();\n  if (!t || !t.access_token) return null;\n  if (t.expires_at && Date.now() / 1000 >= Number(t.expires_at)) {\n    localStorage.removeItem(TOKEN_KEY);\n    return null;\n  }\n  return t;\n}\n\nfunction logout() {\n  localStorage.removeItem(TOKEN_KEY);\n  docum" +
  "ent.getElementById(\"logoutBtn\").classList.add(\"hidden\");\n  window.pendingLogin = null;\n  document.getElementById(\"authCard\").classList.remove(\"hidden\");\n  document.getElementById(\"authOtpBox\").classList.add(\"hidden\");\n  document.getElementById(\"login\").classList.add(\"hidden\");\n  document.getElementById(\"home\").classList.add(\"hidden\");\n  document.getElementById(\"section\").classList.add(\"hidden\");\n  setAuthStatus(\"Đã xóa token. Vui lòng đăng nhập lại.\");\n  showResult(\"Chưa có dữ liệu.\");\n}\n\nfunction updateLoginUI() {\n  const token = getValidToken();\n  const loginCard = document.getElementById(\"authCard\");\n  if (token) {\n    loginCard.classList.add(\"hidden\");\n    document.getElementById(\"logoutBtn\").classList.remove(\"hidden\");\n    const name = token.ten_nv || token.username || \"người dùng\";\n    setAuthStatus(\"✅ Đang đăng nhập: \" + name + \"\\nToken còn hiệu lực.\");\n    document.getElementById(\"login\").classList.remove(\"hidden\");\n  } else {\n    loginCard.classList.remove(\"hidden\");\n    document.getElementById(\"login\").classList.add(\"hidden\");\n  }\n}\n\nwindow.addEventListener(\"DOMContentLoaded\", updateLoginUI);\n\nasync function postJson(url, data, headers={}) {\n  const response = await fetch(url, {\n    method: \"POST\",\n    headers: Object.assign({\n      \"Content-Type\": \"application/json\"\n    }, headers),\n    body: JSON.stringify(data)\n  });\n  let body;\n  const text = await response.text();\n  try { body = JSON.parse(text); } catch { body = text; }\n  if (!response.ok) {\n    const err = new Error(\"HTTP \" + response.status);\n    err.status = response.status;\n    err.body = body;\n    throw err;\n  }\n  return body;\n}\n\nasync function loginStep1() {\n  const username = document.getElementById(\"username\").value.trim();\n  const password = document.getElementById(\"password\").value;\n\n  if (!use" +
  "rname || !password) {\n    setAuthStatus(\"❌ Vui lòng nhập username và password.\");\n    return;\n  }\n\n  setAuthStatus(\"⏳ [1] Đang xác thực tài khoản...\");\n\n  const payload = {\n    username,\n    password,\n    os_type: \"1\",\n    mobile_id: MOBILE_ID,\n    device_id: DEVICE_ID\n  };\n\n  try {\n    const data1 = await postJson(API_1, payload, {\n      \"User-Agent\": \"Dart/3.10 (dart:io)\"\n    });\n\n    showResult(data1);\n\n    if (data1.error !== null && data1.error !== undefined) {\n      setAuthStatus(\"❌ API 1 thất bại.\\n\" + JSON.stringify(data1, null, 2));\n      return;\n    }\n\n    const data = data1.data || {};\n    const secretCode = data.secretCode;\n\n    if (!secretCode) {\n      setAuthStatus(\"❌ Không nhận được secretCode.\");\n      return;\n    }\n\n    // Chỉ giữ secretCode tạm thời trong JS, không lưu mật khẩu.\n    window.pendingLogin = {\n      username,\n      secretCode,\n      ten_nv: data.ten_nv || null,\n      sdt: data.sdt || null\n    };\n\n    document.getElementById(\"authOtpBox\").classList.remove(\"hidden\");\n    setAuthStatus(\n      \"✅ API 1 thành công.\\n\" +\n      \"Tên nhân viên: \" + (data.ten_nv || \"\") + \"\\n\" +\n      \"Số điện thoại: \" + (data.sdt || \"\") + \"\\n\\n\" +\n      \"OTP đã được gửi. Nhập OTP để tiếp tục.\"\n    );\n  } catch (e) {\n    setAuthStatus(\"❌ Lỗi API 1:\\n\" + (e.body ? JSON.stringify(e.body, null, 2) : e.message));\n  }\n}\n\nasync function loginStep2() {\n  if (!window.pendingLogin) {\n    setAuthStatus(\"❌ Chưa thực hiện bước 1.\");\n    return;\n  }\n\n  const otp = document.getElementById(\"otp\").value.trim();\n  if (!otp) {\n    setAuthStatus(\"❌ OTP không được để trống.\");\n    return;\n  }\n\n  setAuthStatus(\"⏳ [2] Đang xác thực OTP...\");\n\n  const p = window.pendingLogin;\n  const payload = {\n    grant_type: \"password\",\n    client_id: \"clientapp\",\n    client_secret: \"password\",\n    sec" +
  "retCode: p.secretCode,\n    otp\n  };\n\n  try {\n    const data2 = await postJson(API_2, payload, {\n      \"User-Agent\": \"Dart/3.10 (dart:io)\"\n    });\n\n    showResult(data2);\n\n    const access_token = data2.access_token;\n    if (!access_token) {\n      setAuthStatus(\"❌ Không nhận được access_token.\");\n      return;\n    }\n\n    const expires_in = Number(data2.expires_in || 0);\n    const tokenData = {\n      username: p.username,\n      ten_nv: p.ten_nv,\n      sdt: p.sdt,\n      os_type: \"1\",\n      device_id: DEVICE_ID,\n      mobile_id: MOBILE_ID,\n      secretCode: p.secretCode,\n      access_token,\n      refresh_token: data2.refresh_token || null,\n      token_type: data2.token_type || null,\n      expires_in: data2.expires_in || null,\n      expires_at: expires_in ? Date.now() / 1000 + expires_in : null,\n      scope: data2.scope || null\n    };\n\n    saveToken(tokenData);\n    fetch(API_BASE+'/api/log-login', {\n      method:'POST',\n      headers:{'Content-Type':'application/json'},\n      body:JSON.stringify({app:'MODEM',username:p.username})\n    }).catch(()=>{});\n\n    window.pendingLogin = null;\n\n    setAuthStatus(\n      \"✅ ĐĂNG NHẬP THÀNH CÔNG.\\n\" +\n      \"Token đã được lưu trong localStorage với key: \" + TOKEN_KEY\n    );\n    showResult(tokenData);\n    document.getElementById(\"authCard\").classList.add(\"hidden\");\n    document.getElementById(\"logoutBtn\").classList.remove(\"hidden\");\n    document.getElementById(\"login\").classList.remove(\"hidden\");\n  } catch (e) {\n    setAuthStatus(\"❌ OTP không hợp lệ hoặc login thất bại.\\n\" +\n      (e.body ? JSON.stringify(e.body, null, 2) : e.message));\n  }\n}\n\n\n\n\nconst API=API_BASE+'/api/modem';\nconst TOKEN_ID='SDK_TECH';\nlet serial='', modelName='', current='';\nlet wanConfigList=[];\nlet wifiConfigList=[];\n// Cache là nguồn dữ liệu duy nhất cho màn hình S" +
  "ửa sau khi đã Xem cấu hình.\n\nfunction $(id){return document.getElementById(id)}\nfunction esc(v){return String(v??'').replace(/[&<>\"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[m]))}\nfunction toast(msg,ok=true){const t=$('toast');t.textContent=msg;t.style.display='block';setTimeout(()=>t.style.display='none',2600)}\nfunction status(msg,ok=true){$('status').textContent=msg;$('status').className='status '+(ok?'ok':'err')}\nfunction row(k,v){return `<div class=\"row\"><span>${esc(k)}</span><span>${esc(v)}</span></div>`}\nfunction item(title, rows){return `<div class=\"item\"><h3>${esc(title)}</h3>${rows.map(x=>row(x[0],x[1])).join('')}</div>`}\nfunction bool(v){return v===true?'True':v===false?'False':v}\n\n\nlet activeProgress=null;\n\nfunction ensureFeatureProgress(){\n  const panel=$('panel');\n  let box=document.getElementById('featureProgress');\n  if(!box){\n    box=document.createElement('div');\n    box.id='featureProgress';\n    box.className='feature-progress';\n    box.innerHTML=`\n      <div class=\"fp-head\"><span id=\"fpText\">⏳ Đang xử lý...</span><span id=\"fpPercent\">0%</span></div>\n      <div class=\"fp-track\"><div id=\"fpBar\" class=\"fp-bar\"></div></div>\n      <div id=\"fpLog\" class=\"fp-log\"></div>`;\n    panel.prepend(box);\n  }\n  return box;\n}\n\nasync function paint(){\n  await new Promise(resolve=>requestAnimationFrame(()=>resolve()));\n}\n\nlet actionBusy=false;\nfunction beginAction(){\n  if(actionBusy){toast('⏳ Đang có thao tác khác, vui lòng chờ...',false);return false}\n  actionBusy=true;\n  return true;\n}\nfunction endAction(){actionBusy=false}\nfunction numField(id,label,min=0){\n  const el=$(id);\n  const n=Number(el?.value);\n  if(!Number.isFinite(n)||n<min) throw new Error(`${label} không hợp lệ.`);\n  return n;\n}\n\nfunction progressStart(text='Đang xử lý...'){\n  c" +
  "onst box=ensureFeatureProgress();\n  box.style.display='block';\n  $('fpBar').style.background='#2563eb';\n  $('fpText').textContent='⏳ '+text;\n  $('fpPercent').textContent='0%';\n  $('fpBar').style.width='0%';\n  $('fpLog').textContent='';\n}\n\nfunction progressStep(text,percent){\n  const box=ensureFeatureProgress();\n  box.style.display='block';\n  $('fpText').textContent='⏳ '+text;\n  $('fpPercent').textContent=Math.max(0,Math.min(100,percent))+'%';\n  $('fpBar').style.width=Math.max(0,Math.min(100,percent))+'%';\n  const log=$('fpLog');\n  log.textContent+=(log.textContent?'\\n':'')+'• '+text;\n  log.scrollTop=log.scrollHeight;\n}\n\nfunction progressDone(text='Hoàn tất'){\n  progressStep('✓ '+text,100);\n}\n\nfunction progressError(text){\n  const box=ensureFeatureProgress();\n  box.style.display='block';\n  $('fpText').textContent='✗ '+text;\n  $('fpPercent').textContent='LỖI';\n  $('fpBar').style.width='100%';\n  $('fpBar').style.background='#dc2626';\n  const log=$('fpLog');\n  log.textContent+=(log.textContent?'\\n':'')+'• ✗ '+text;\n}\n\n/* ============================================================\n   API THI CÔNG - TRA CỨU SERIAL VẬT TƯ\n   Luồng: Username/Password -> OTP -> access_token -> API này.\n   KHÔNG liên quan đến MODEM_API/getDeviceInfo.\n   ============================================================ */\nconst THICONG_API=API_BASE+'/api/thicong/dsVatTuThiCong';\nconst THICONG_MENU_ID='11226';\n\n// app-secret theo cách app OneBSS tạo từ token + thông tin trình duyệt.\n// Không dùng app-secret HAR cố định vì dễ hết hiệu lực/không khớp thiết bị.\nfunction buildThicongAppSecret(token){\n  const data={\n    device_id: token?.device_id || DEVICE_ID,\n    device_ip:'',\n    device_name:navigator.userAgent || '',\n    mac_address:'',\n    mobile_id:token?.mobile_id || MOBILE_ID,\n    app_id:APP_ID,\n   " +
  " app_version:APP_VERSION,\n    os_version:navigator.platform || ''\n  };\n  return btoa(unescape(encodeURIComponent(JSON.stringify(data))));\n}\n\nasync function traCuuSerialVatTu(serialNumber){\n  const tokenData=getValidToken();\n  const accessToken=tokenData && tokenData.access_token;\n  if(!accessToken){\n    throw new Error('Chưa đăng nhập OneBSS hoặc access_token đã hết hạn.');\n  }\n\n  const url=THICONG_API+'?serial='+encodeURIComponent(serialNumber);\n  const response=await fetch(url,{\n    method:'POST',\n    headers:{\n      'accept':'application/json',\n      'content-type':'application/json',\n      'authorization':'Bearer '+accessToken,\n      'selectedmenuid':THICONG_MENU_ID,\n      'app-secret':buildThicongAppSecret(tokenData)\n    },\n    body:'{\"menu_id\":11226}'\n  });\n\n  const text=await response.text();\n  let data;\n  try{ data=JSON.parse(text); }\n  catch(e){ data={message:text}; }\n\n  if(!response.ok){\n    const detail=data?.message || data?.error || text || ('HTTP '+response.status);\n    throw new Error('HTTP '+response.status+' — '+detail);\n  }\n\n  if(data?.error && data.error!=='BSS-00000000'){\n    throw new Error(data.message || data.error || 'API Thi Công báo lỗi');\n  }\n\n  const first=Array.isArray(data?.data) ? data.data[0] : null;\n  const vt=first?.vatTuThiCong;\n\n  return {\n    serialVatTu:vt?.serial || '',\n    maVatTu:vt?.maVatTu || '',\n    tenVatTu:vt?.tenVatTu || '',\n    partNumber:vt?.partNumber || '',\n    data\n  };\n}\n\nconst MODEM_API=API_BASE+'/api/modem';\nconst MODEM_TOKEN_KEY='FVcLoGQybQAkTn3qR1WcEVAiLCOHxwEp';\nconst MODEM_TOKEN_ID='SDK_TECH';\n\nfunction modemHeaders(){\n  return {\n    'accept':'application/json',\n    'content-type':'application/json',\n    'token-key':MODEM_TOKEN_KEY,\n    'token-id':MODEM_TOKEN_ID\n  };\n}\n\nasync function apiGet(path,params={}){\n co" +
  "nst label=(params.command||path.split('/').pop()||'API');\n progressStart(`Đang gọi ${label}...`);\n progressStep(`Đang gửi GET ${path} trực tiếp...`,20);\n await paint();\n const q=Object.keys(params).map(k=>encodeURIComponent(k)+'='+encodeURIComponent(params[k]==null?'':params[k])).join('&');\n const url=MODEM_API+'/'+String(path||'').replace(/^\\/+/, '')+(q?'?'+q:'');\n try{\n   const r=await fetch(url,{method:'GET',headers:modemHeaders()});\n   const text=await r.text();\n   let data;\n   try{data=JSON.parse(text)}catch(e){data={errorMessage:text}}\n   progressStep(`API ${label} đã phản hồi...`,75);\n   if(!r.ok || (data.errorCode!==undefined && Number(data.errorCode)!==200)){\n     throw new Error(data.errorMessage||('HTTP '+r.status));\n   }\n   progressStep(`Đã nhận dữ liệu ${label}.`,90);\n   return data;\n }catch(e){\n   throw new Error(e&&e.message?e.message:String(e));\n }\n}\n\nasync function apiPost(payload){\n const command=payload?.command||'API POST';\n progressStart(`Đang gọi ${command}...`);\n progressStep(`Đang chuẩn bị payload ${command}...`,15);\n await paint();\n try{\n   const r=await fetch(MODEM_API+'/deviceConfig',{\n     method:'POST',\n     headers:modemHeaders(),\n     body:JSON.stringify(payload||{})\n   });\n   const text=await r.text();\n   let data;\n   try{data=JSON.parse(text)}catch(e){data={errorMessage:text}}\n   progressStep(`API ${command} đã phản hồi...`,80);\n   if(!r.ok || (data.errorCode!==undefined && Number(data.errorCode)!==200)){\n     throw new Error(data.errorMessage||('HTTP '+r.status));\n   }\n   progressStep(`Đã nhận kết quả ${command}.`,92);\n   return data;\n }catch(e){\n   throw new Error(e&&e.message?e.message:String(e));\n }\n}\n\nfunction parseSerialInput(value){\n  return [\n    ...new Set(\n      String(value || '')\n        .split(';')\n        .map(function(x){ " +
  "return x.trim(); })\n        .filter(Boolean)\n    )\n  ];\n}\n\n/*\n * Một ô nhập duy nhất:\n * - 1 Serial              -> kết nối modem -> vào MENU CẤU HÌNH MODEM\n * - nhiều Serial có dấu ; -> tra cứu menID + PPPoE\n */\nasync function handleSerialInput(){\n  const value=$('serial')?.value || '';\n  const serials=parseSerialInput(value);\n\n  if(!serials.length){\n    toast('Nhập Serial Number',false);\n    return;\n  }\n\n  if(serials.length===1){\n    $('serial').value=serials[0];\n    await connectDevice();\n    return;\n  }\n\n  if(serials.length>50){\n    toast('Tối đa 50 Serial mỗi lần',false);\n    return;\n  }\n\n  await getBulkDeviceInfo(serials);\n}\n\nfunction setBulkProgress(text,percent,log){\n  const box=$('bulkProgress');\n  if(!box)return;\n\n  box.classList.remove('hidden');\n  $('bulkProgressText').textContent=text;\n  $('bulkProgressPercent').textContent=percent+'%';\n  $('bulkProgressBar').style.width=percent+'%';\n\n  if(log){\n    const logBox=$('bulkProgressLog');\n    logBox.textContent += (logBox.textContent ? '\\n' : '') + '• ' + log;\n    logBox.scrollTop=logBox.scrollHeight;\n  }\n}\n\nfunction renderBulkResults(rows){\n  const summary=$('bulkSummary');\n  const result=$('bulkResult');\n\n  const total=rows.length;\n  const materialSuccess=rows.filter(function(x){return x.materialOk}).length;\n  const modemSuccess=rows.filter(function(x){return x.modemOk}).length;\n  const fail=rows.filter(function(x){return !x.modemOk || !x.materialOk}).length;\n\n  summary.innerHTML=\n    '<div class=\"bulk-summary\">' +\n    'Tổng <b>'+total+'</b> Serial | ' +\n    'Modem <b>'+modemSuccess+'</b> | ' +\n    'Vật tư <b>'+materialSuccess+'</b> | ' +\n    'Có lỗi <b>'+fail+'</b>' +\n    '</div>';\n\n  let html=\n    '<div class=\"bulk-table-wrap\">' +\n    '<table class=\"bulk-table\">' +\n    '<thead><tr>' +\n    '<th>#</th>' +\n    " +
  "'<th>Serial / Serial Vật tư</th>' +\n    '<th>MenID / PPPoE</th>' +\n    '<th>Tên vật tư</th>' +\n    '<th>Trạng thái</th>' +\n    '</tr></thead><tbody>';\n\n  rows.forEach(function(row,index){\n    const status=[];\n    if(row.modemOk) status.push('✓ Modem');\n    else status.push('✗ Modem: '+(row.modemError||'lỗi'));\n    if(row.materialOk) status.push('✓ Vật tư');\n    else status.push('✗ Vật tư: '+(row.materialError||'lỗi'));\n\n    html +=\n      '<tr>' +\n      '<td>'+(index+1)+'</td>' +\n      '<td>'+\n        esc(row.serial || '')+\n        (row.materialOk && row.serialVatTu ? '<br><b>'+esc(row.serialVatTu)+'</b>' : '')+\n      '</td>' +\n      '<td>'+\n        (row.modemOk\n          ? esc(row.menID || 'Không tìm thấy')+'<br><b>'+esc(row.pppoeUsername || 'Không tìm thấy')+'</b>'\n          : '—')+\n      '</td>' +\n      '<td>'+\n        (row.materialOk\n          ? esc(String(row.tenVatTu || '').replace(/^Thiết bị đầu cuối\\s*/i,''))\n          : '—')+\n      '</td>' +\n      '<td class=\"'+(row.modemOk && row.materialOk ? 'bulk-ok' : 'bulk-err')+'\">'+\n        ((row.modemOk && row.materialOk) ? 'Tìm Thấy' : status.map(esc).join('<br>'))+\n      '</td>' +\n      '</tr>';\n  });\n\n  html+='</tbody></table></div>';\n  result.innerHTML=html;\n}\n\nasync function getBulkDeviceInfo(serials){\n  if(!serials){\n    serials=parseSerialInput($('serial')?.value || '');\n  }\n\n  if(!serials.length){\n    toast('Nhập Serial Number',false);\n    return;\n  }\n\n  const area=$('bulkSearchArea');\n  if(area)area.classList.remove('hidden');\n\n  $('bulkSummary').innerHTML='';\n  $('bulkResult').innerHTML='';\n  $('bulkProgressLog').textContent='';\n\n  const rows=[];\n  setBulkProgress('Bắt đầu...',0);\n\n  for(let i=0;i<serials.length;i++){\n    const sn=serials[i];\n    const row={\n      serial:sn,\n      menID:'',\n      pppoeUsername:" +
  "'',\n      serialVatTu:'',\n      tenVatTu:'',\n      modemOk:false,\n      materialOk:false,\n      modemError:'',\n      materialError:''\n    };\n\n    /* ---------------------------------------------------------\n       1. API MODEM GỐC: giữ nguyên getDeviceInfo.\n       --------------------------------------------------------- */\n    try{\n      setBulkProgress(\n        'Đang lấy '+(i+1)+'/'+serials.length,\n        Math.round((i/serials.length)*100),\n        'GET getDeviceInfo → '+sn\n      );\n\n      const data=await apiGet('/getDeviceInfo',{serialNumber:sn});\n      const body=data?.body;\n\n      if(!body || typeof body!=='object'){\n        throw new Error('API không có body');\n      }\n\n      row.menID=body.menID ?? '';\n      row.pppoeUsername=body.pppoeUsername ?? '';\n      row.modemOk=true;\n    }catch(e){\n      row.modemError=e?.message || String(e);\n    }\n\n    renderBulkResults(rows.concat([row]));\n\n    /* ---------------------------------------------------------\n       2. API THI CÔNG: hoàn toàn độc lập với getDeviceInfo.\n       Dùng access_token lấy từ Username/Password + OTP.\n       --------------------------------------------------------- */\n    try{\n      setBulkProgress(\n        'Tra cứu vật tư '+(i+1)+'/'+serials.length,\n        Math.round(((i+0.5)/serials.length)*100),\n        'POST dsVatTuThiCong → '+sn\n      );\n\n      const vt=await traCuuSerialVatTu(sn);\n      row.serialVatTu=vt.serialVatTu;\n      row.tenVatTu=vt.tenVatTu;\n      row.materialOk=!!row.serialVatTu;\n\n      if(!row.materialOk){\n        row.materialError='API thành công nhưng không có vatTuThiCong.serial';\n      }\n    }catch(e){\n      row.materialError=e?.message || String(e);\n    }\n\n    rows.push(row);\n    renderBulkResults(rows);\n\n    const logParts=[];\n    logParts.push(row.modemOk\n      ? '✓ Modem '+" +
  "sn+' → menID: '+(row.menID||'không có')+' | PPPoE: '+(row.pppoeUsername||'không có')\n      : '✗ Modem '+sn+' → '+row.modemError);\n    logParts.push(row.materialOk\n      ? '✓ Vật tư '+sn+' → '+row.serialVatTu\n      : '✗ Vật tư '+sn+' → '+row.materialError);\n\n    setBulkProgress(\n      'Đã xử lý '+(i+1)+'/'+serials.length,\n      Math.round(((i+1)/serials.length)*100),\n      logParts.join('\\n')\n    );\n\n    await new Promise(function(resolve){setTimeout(resolve,100);});\n  }\n\n  const materialSuccess=rows.filter(function(x){return x.materialOk}).length;\n  const modemSuccess=rows.filter(function(x){return x.modemOk}).length;\n\n  setBulkProgress(\n    '✓ Hoàn tất '+serials.length+' Serial',\n    100,\n    'Hoàn tất: Modem '+modemSuccess+'/'+serials.length+\n    ' | Vật tư '+materialSuccess+'/'+serials.length\n  );\n}\n\nfunction clearBulkResult(){\n  if($('bulkSummary'))$('bulkSummary').innerHTML='';\n  if($('bulkResult'))$('bulkResult').innerHTML='';\n  if($('bulkProgressLog'))$('bulkProgressLog').textContent='';\n  if($('bulkProgressBar'))$('bulkProgressBar').style.width='0%';\n  if($('bulkProgressPercent'))$('bulkProgressPercent').textContent='0%';\n  if($('bulkProgressText'))$('bulkProgressText').textContent='Đang xử lý...';\n  if($('bulkProgress'))$('bulkProgress').classList.add('hidden');\n  if($('bulkSearchArea'))$('bulkSearchArea').classList.add('hidden');\n}\n\n/*\n * Từ MENU CẤU HÌNH MODEM quay về đúng màn hình KẾT NỐI MODEM\n * (màn hình có ô Serial), không logout và không xóa token.\n */\nfunction backToConnection(){\n  const section=$('section');\n  const home=$('home');\n  const login=$('login');\n\n  if(section) section.classList.add('hidden');\n  if(home) home.classList.add('hidden');\n  if(login) login.classList.remove('hidden');\n\n  current='';\n\n  if($('bulkSearchArea')) $('bulkSearchArea')." +
  "classList.add('hidden');\n}\n\nasync function connectDevice(){\n serial=$('serial').value.trim(); if(!serial){toast('Nhập Serial Number',false);return}\n const loginBox=$('login');\n let p=loginBox.querySelector('#connectProgress');\n if(!p){\n   p=document.createElement('div');p.id='connectProgress';p.className='feature-progress';\n   p.innerHTML='<div class=\"fp-head\"><span id=\"cpText\">⏳ Đang kết nối...</span><span id=\"cpPercent\">0%</span></div><div class=\"fp-track\"><div id=\"cpBar\" class=\"fp-bar\"></div></div><div id=\"cpLog\" class=\"fp-log\"></div>';\n   loginBox.appendChild(p);\n }\n p.style.display='block';\n const cp=(t,n)=>{p.querySelector('#cpText').textContent='⏳ '+t;p.querySelector('#cpPercent').textContent=n+'%';p.querySelector('#cpBar').style.width=n+'%';};\n try{\n  cp('Đang kiểm tra Serial Number...',20); await paint();\n  cp('Đang gọi API getDeviceInfo...',45);\n  const d=await apiGet('/getDeviceInfo',{serialNumber:serial});\n  cp('Đang lấy thông tin thiết bị...',80);\n  modelName=d?.body?.modelName||'GW040-NS';\n  $('login').classList.add('hidden');$('home').classList.remove('hidden');status('Kết nối thành công');\n }catch(e){cp('✗ '+e.message,100);toast(e.message,false)}\n}\nfunction openSection(name){current=name;$('home').classList.add('hidden');$('section').classList.remove('hidden');showView()}\nfunction goHome(){$('section').classList.add('hidden');$('home').classList.remove('hidden');current=''}\nfunction showView(){ if(current==='firmware')return viewFirmware(); if(current==='device')return viewDevice(); if(current==='wifi')return viewWifi(); if(current==='wan')return viewWan(); if(current==='lan')return viewLan(); if(current==='optical')return viewOptical(); if(current==='ping')return viewPing(); if(current==='password')return viewPassword(); if(current==='reboot')return vie" +
  "wReboot(); if(current==='topology')return viewTopology() }\nfunction showSet(){ if(current==='firmware')return viewFirmware(); if(current==='device')return noSet('DEVICE INFO / SLID'); if(current==='wifi')return setWifi(); if(current==='wan')return setWanMenu(); if(current==='lan')return setLan(); if(current==='optical')return noSet('OPTICAL'); if(current==='ping')return setPing(); if(current==='password')return setPassword(); if(current==='reboot')return setReboot(); if(current==='topology')return noSet('TOPOLOGY - Xem cấu hình') }\n\n/* UPDATE FIRMWARE: API dựa trên HAR do người dùng cung cấp */\nlet firmwareList=[];\nlet firmwareCurrentVersion='';\n\nasync function viewFirmware(){\n  $('panel').innerHTML='<h2>UPDATE FIRMWARE</h2><div class=\"status\">Đang lấy danh sách firmware...</div>';\n  progressStart('Đang lấy danh sách firmware...');\n  firmwareList=[];\n  try{\n    progressStep('Đang đọc phiên bản hiện tại...',20);\n    let info=null;\n    try{\n      info=await apiGet('/getDeviceInfo',{serialNumber:serial});\n      firmwareCurrentVersion=info?.body?.softwareVersion || '';\n      modelName=info?.body?.modelName || modelName;\n    }catch(e){ firmwareCurrentVersion=''; }\n    progressStep('Đang gọi getFirmwareList...',45);\n    const d=await apiGet('/getFirmwareList',{modelName,serialNumber:serial});\n    if(d?.errorCode!==undefined && Number(d.errorCode)!==200)\n      throw new Error(d.errorMessage || 'Không lấy được danh sách firmware');\n    firmwareList=Array.isArray(d?.body)?d.body:[];\n    if(!firmwareList.length) throw new Error('API không trả về danh sách firmware cho model/serial này.');\n    const options=firmwareList.map((f,i)=>{\n      const version=f.softwareVersion || f.firmwareName || ('Firmware '+(i+1));\n      const current=firmwareCurrentVersion && version===firmwareCurren" +
  "tVersion ? ' — ĐANG DÙNG' : '';\n      return `<option value=\"${i}\">${esc(version+current)}${f.firmwareName && f.softwareVersion!==f.firmwareName ? ' · '+esc(f.firmwareName):''}</option>`;\n    }).join('');\n    $('panel').innerHTML=`\n      <h2>UPDATE FIRMWARE</h2>\n      <div class=\"status\">Model: <b>${esc(modelName)}</b><br>Serial: <b>${esc(serial)}</b><br>Firmware hiện tại: <b>${esc(firmwareCurrentVersion||'Không xác định')}</b></div>\n      <label>Chọn phiên bản firmware</label>\n      <select id=\"firmwareChoice\">${options}</select>\n      <div id=\"firmwareDetail\" class=\"status\"></div>\n      <button type=\"button\" onclick=\"updateFirmware()\">⬆️ CẬP NHẬT FIRMWARE</button>\n      <button type=\"button\" class=\"secondary\" style=\"margin-top:8px\" onclick=\"viewFirmware()\">🔄 TẢI LẠI DANH SÁCH</button>\n      <div class=\"status\" style=\"margin-top:10px\">⚠️ Không tắt nguồn modem hoặc ngắt kết nối trong quá trình cập nhật. Modem có thể tự khởi động lại. Chỉ cập nhật firmware đúng model.</div>`;\n    $('firmwareChoice').addEventListener('change',renderFirmwareDetail);\n    renderFirmwareDetail();\n    progressDone('Đã tải '+firmwareList.length+' phiên bản firmware');\n  }catch(e){\n    progressError(e.message);\n    $('panel').innerHTML='<h2>UPDATE FIRMWARE</h2><div class=\"status err\">'+esc(e.message)+'</div><button onclick=\"viewFirmware()\">Thử lại</button>';\n  }\n}\nfunction renderFirmwareDetail(){\n  const f=firmwareList[Number($('firmwareChoice')?.value)];\n  const box=$('firmwareDetail');\n  if(!f||!box)return;\n  box.innerHTML='Phiên bản: <b>'+esc(f.softwareVersion||'Không rõ')+'</b><br>Tên file: '+esc(f.firmwareName||'Không rõ');\n}\nasync function updateFirmware(){\n  const select=$('firmwareChoice');\n  const f=firmwareList[Number(select?.value)];\n  if(!f || !f.url){toast('Firmware không có URL hợ" +
  "p lệ.',false);return}\n  if(f.softwareVersion && f.softwareVersion===firmwareCurrentVersion){\n    toast('Modem đang dùng phiên bản này.',false);return;\n  }\n  const version=f.softwareVersion||f.firmwareName||'đã chọn';\n  if(!confirm('Xác nhận cập nhật firmware '+version+' cho modem '+serial+' ('+modelName+')?\\\\n\\\\nKhông tắt nguồn hoặc ngắt kết nối trong khi cập nhật.'))return;\n  if(!beginAction())return;\n  try{\n    progressStart('Đang gửi lệnh cập nhật firmware...');\n    progressStep('Đang gửi command updateFirm...',35);\n    const result=await apiPost({\n      command:'updateFirm',\n      modelName,\n      serialNumber:serial,\n      body:{fileURL:f.url}\n    });\n    if(result?.errorCode!==undefined && Number(result.errorCode)!==200)\n      throw new Error(result.errorMessage||'API cập nhật firmware báo lỗi');\n    progressDone('API đã nhận lệnh cập nhật firmware');\n    toast('Đã gửi lệnh cập nhật firmware. Chờ modem hoàn tất và kiểm tra lại phiên bản.');\n    const panel=$('panel');\n    if(panel){\n      const notice=document.createElement('div');\n      notice.className='status ok';\n      notice.textContent='API trả về: '+(result?.errorMessage||'SUCCESS')+'. Đây là xác nhận nhận lệnh, chưa chứng minh modem đã cài xong firmware.';\n      panel.prepend(notice);\n    }\n  }catch(e){\n    progressError(e.message);toast('Cập nhật thất bại: '+e.message,false);\n  }finally{endAction()}\n}\n\nfunction noSet(x){$('panel').innerHTML=`<h2>${esc(x)}</h2><div class=\"status\">Chưa có API SET trong dữ liệu capture đã cung cấp.</div>`}\n\nasync function viewDevice(){\n $('panel').innerHTML='<h2>DEVICE INFO</h2><div class=\"status\">Đang tải...</div>';\n progressStart('Đang lấy DEVICE INFO...');\n try{progressStep('Đang gọi API getDeviceInfo...',35);const d=await apiGet('/getDeviceInfo',{serialNumber:serial});pr" +
  "ogressStep('Đang xử lý dữ liệu...',80);const b=d.body||{};\n $('panel').innerHTML='<h2>DEVICE INFO</h2>'+item('',[\n ['Serial Number',b.adslSerialNumber],['Model',b.modelName],['Firmware',b.softwareVersion],['IP Address',b.ipAddress],['MAC Address',b.macAddress],['PPPoE',b.pppoeUsername],['Link State',b.linkState],['Uptime',b.deviceUptime]\n ].map(x=>x));progressDone('Đã tải DEVICE INFO');}catch(e){progressError(e.message);errorPanel(e)}\n}\nasync function viewWifi(){\n  $('panel').innerHTML='<h2>WIFI</h2><div class=\"status\">Đang tải...</div>';\n  progressStart('Đang lấy cấu hình WIFI...');\n  try{\n    progressStep('Đang gọi API getWifiConfig...',35);\n    const d=await apiGet('/getDeviceConfig',{\n      modelName,\n      serialNumber:serial,\n      command:'getWifiConfig'\n    });\n    progressStep('Đang phân tích 2.4G / 5G...',80);\n\n    // Lưu toàn bộ cấu hình WIFI để mục SET WIFI dùng lại.\n    wifiConfigList=Array.isArray(d?.body)?d.body:[];\n\n    let h='<h2>WIFI 2.4G</h2>';\n    h+=wifiConfigList.filter(x=>x.type==='Wireless 2.4G').map(x=>wifiCard(x)).join('');\n    h+='<h2>WIFI 5G</h2>';\n    h+=wifiConfigList.filter(x=>x.type==='Wireless 5G').map(x=>wifiCard(x)).join('');\n\n    $('panel').innerHTML=h+\n      (!wifiConfigList.length?'<div class=\"status\">API không trả về cấu hình WIFI.</div>':'');\n    progressDone('Đã tải WIFI');\n  }catch(e){\n    progressError(e.message);\n    errorPanel(e);\n  }\n}\n\nfunction wifiCard(x){return item(`Profile ${x.index}`,[['Enable',bool(x.enable)],['SSID',x.ssid],['Auth Mode',x.authMode],['Password',x.password],['Encrypt',x.encrypt]])}\nfunction setWifi(){\n  if(!Array.isArray(wifiConfigList) || !wifiConfigList.length){\n    $('panel').innerHTML=`<h2>SET WIFI</h2>\n      <div class=\"status err\">Chưa có dữ liệu WIFI. Hãy vào \"Xem cấu hình\" trước.</div>\n      <b" +
  "utton onclick=\"viewWifi()\">XEM CẤU HÌNH WIFI</button>`;\n    return;\n  }\n\n  $('panel').innerHTML=`<h2>SET WIFI</h2>\n    <div class=\"status ok\">✓ Dùng dữ liệu đã lấy từ \"Xem cấu hình WIFI\" — không gọi getWifiConfig lần nữa.</div>\n\n    <label>Băng tần</label>\n    <select id=\"wband\" onchange=\"updateProfiles()\">\n      <option value=\"2\">WiFi 2.4G</option>\n      <option value=\"5\">WiFi 5G</option>\n    </select>\n\n    <label>Profile</label>\n    <select id=\"wprofile\" onchange=\"fillWifiForm()\"></select>\n\n    <div id=\"wifiEditFields\"></div>`;\n\n  updateProfiles();\n}\n\nfunction updateProfiles(){\n  const band=Number($('wband').value);\n  const select=$('wprofile');\n  if(!select) return;\n\n  const type=band===2?'Wireless 2.4G':'Wireless 5G';\n  const list=(wifiConfigList||[]).filter(x=>x.type===type);\n\n  if(!list.length){\n    select.innerHTML='<option value=\"\">Không có profile</option>';\n    $('wifiEditFields').innerHTML='<div class=\"status\">Không có cấu hình '+esc(type)+'.</div>';\n    return;\n  }\n\n  select.innerHTML=list.map((x,i)=>{\n    const idx=x.index??(band===2?i:i+4);\n    const ssid=x.ssid||('Profile '+(i+1));\n    return `<option value=\"${esc(idx)}\">${esc(ssid)} - API index ${esc(idx)}</option>`;\n  }).join('');\n\n  fillWifiForm();\n}\n\nfunction fillWifiForm(){\n  const band=Number($('wband')?.value||2);\n  const selected=Number($('wprofile')?.value);\n  const type=band===2?'Wireless 2.4G':'Wireless 5G';\n\n  // QUAN TRỌNG:\n  // Lấy đúng object đã đọc từ API và đã lưu trong wifiConfigList.\n  const list=(wifiConfigList||[]).filter(v=>v.type===type);\n  let x=list.find(v=>Number(v.index)===selected);\n\n  // Một số API có thể không trả index.\n  if(!x){\n    const pos=list.findIndex((v,i)=>Number(v.index??(band===2?i:i+4))===selected);\n    x=list[pos>=0?pos:0];\n  }\n\n  if(!x){\n    $('wifiEditFields')" +
  ".innerHTML='<div class=\"status err\">Không tìm thấy profile WIFI.</div>';\n    return;\n  }\n\n  // Lưu đúng object gốc đang được sửa.\n  window.currentWifiOriginal=x;\n\n  $('wifiEditFields').innerHTML=`\n    <div class=\"section-title\">Cấu hình đã đọc từ API</div>\n    <div class=\"item\">\n      ${row('Profile Index',x.index)}\n      ${row('Băng tần',x.type)}\n      ${row('Enable',bool(x.enable))}\n      ${row('SSID',x.ssid)}\n      ${row('Auth Mode',x.authMode)}\n      ${row('Encrypt',x.encrypt)}\n    </div>\n\n    <div class=\"section-title\">Form SET WIFI</div>\n\n    <label>SSID</label>\n    <input id=\"wssid\" value=\"${esc(x.ssid??'')}\">\n\n    <label>Password</label>\n    <input id=\"wpass\" type=\"text\" autocomplete=\"off\" value=\"${esc(x.password??'')}\" placeholder=\"Mật khẩu (có thể nhìn thấy)\">\n\n    <label>Enable</label>\n    <select id=\"wenable\">\n      <option value=\"1\" ${x.enable===true?'selected':''}>1 - True</option>\n      <option value=\"0\" ${x.enable===false?'selected':''}>0 - False</option>\n    </select>\n\n    <label>Auth Mode</label>\n    <input id=\"wauth\" value=\"WPAand11i\">\n\n    <label>Encrypt</label>\n    <input id=\"wencrypt\" value=\"AESEncryption\">\n\n    <button class=\"success\" onclick=\"doSetWifi()\">SET WIFI</button>`;\n}\n\nasync function doSetWifi(){\n  if(!beginAction()) return;\n  try{\n    const original=window.currentWifiOriginal;\n    if(!original) throw new Error('Chưa có cấu hình WIFI đã đọc.');\n\n    const ssid=$('wssid').value.trim();\n    const authMode=$('wauth').value.trim();\n    const encrypt=$('wencrypt').value.trim();\n\n    if(!ssid) throw new Error('SSID không được để trống.');\n    if(!authMode) throw new Error('Auth Mode không được để trống.');\n    if(!encrypt) throw new Error('Encrypt không được để trống.');\n\n    /*\n      NGUYÊN TẮC:\n      - original là cấu hình thật đã đọc từ API" +
  ".\n      - Không tự tạo giá trị mặc định.\n      - Chỉ thay những trường người dùng sửa.\n      - Các trường khác giữ nguyên theo cấu hình đã đọc.\n    */\n    const body=JSON.parse(JSON.stringify(original));\n\n    body.enable=$('wenable').value==='1';\n    body.ssid=ssid;\n    body.authMode=authMode;\n    body.encrypt=encrypt;\n\n    if($('wpass').value){\n      body.password=$('wpass').value;\n    }else if(original.password!==undefined){\n      // Không thay mật khẩu nếu người dùng không nhập mật khẩu mới.\n      body.password=original.password;\n    }\n\n    // index phải lấy đúng từ cấu hình đã đọc.\n    if(original.index!==undefined) body.index=original.index;\n\n    const payload={\n      modelName,\n      serialNumber:serial,\n      command:'wifiConfig',\n      body\n    };\n\n    progressStart('Đang SET WIFI...');\n    progressStep('Đang chuẩn bị payload WIFI từ cấu hình đã đọc...',25);\n    progressStep('Đang gửi API wifiConfig...',55);\n    await apiPost(payload);\n\n    progressDone('SET WIFI thành công');\n    toast('✓ SET WIFI thành công');\n\n    // Cập nhật chính object cache bằng dữ liệu đã SET.\n    Object.assign(original,body);\n    fillWifiForm();\n\n  }catch(e){\n    progressError(e.message);\n    toast(e.message,false);\n  }finally{\n    endAction();\n  }\n}\n\nasync function viewWan(){\n  $('panel').innerHTML='<h2>WAN CONFIG</h2><div class=\"status\">Đang tải...</div>';\n  progressStart('Đang lấy cấu hình WAN...');\n  try{\n    progressStep('Đang gọi API getWanConfig...',35);\n    const d=await apiGet('/getDeviceConfig',{\n      modelName,\n      serialNumber:serial,\n      command:'getWanConfig'\n    });\n    progressStep('Đang xử lý danh sách WAN...',80);\n\n    // Lưu cấu hình WAN để mục Sửa WAN dùng lại, không gọi API lần 2.\n    wanConfigList=Array.isArray(d?.body)?d.body:[];\n\n    $('panel').innerHTML='<h" +
  "2>WAN CONFIG</h2>'+\n      (wanConfigList.length\n        ? wanConfigList.map((x,i)=>wanCard(x,i+1)).join('')\n        : '<div class=\"status\">API không trả về cấu hình WAN.</div>');\n\n    progressDone('Đã tải WAN');\n  }catch(e){\n    progressError(e.message);\n    errorPanel(e);\n  }\n}\n\nfunction wanCard(x,n){\n let r=[['WAN Index',x.wanIndex],['Enable',bool(x.enable)],['Type',x.wanType],['Connection',x.connectionType],['Name',x.wanName],['Interface',x.wanIfname],['Status',x.connectionStatus],['VLAN',x.vlanMuxID],['VLAN Priority',x.vlanPriority],['IPv4',x.externalIPAdress],['IPv4 Enable',bool(x.ipv4Enable)],['NAT',bool(x.natEnable)],['Firewall',bool(x.firewallEnable)],['Username',x.userName],['Password',x.password],['Addressing',x.addressingType],['Gateway',x.defaultGateway],['Default GW',bool(x.isDefaultGateway)],['Service',x.serviceList]];\n const has6=[x.externalIPv6Address,x.defaultIPv6Gateway,x.ipv6DnsServer,x.ipv6Status].some(v=>v!==null&&v!==undefined&&String(v).trim()!==''&&String(v)!=='0.0.0.0');\n if(has6)r.push(['IPv6',x.externalIPv6Address],['IPv6 Gateway',x.defaultIPv6Gateway],['IPv6 DNS',x.ipv6DnsServer],['IPv6 Status',x.ipv6Status]);\n return item(`WAN #${x.wanIndex??n}`,r)\n}\nfunction setWanMenu(){\n $('panel').innerHTML=`<h2>SET WAN</h2><div class=\"grid\"><button onclick=\"wanDeleteForm()\">Xóa WAN</button><button onclick=\"wanUpdateForm()\">Sửa WAN</button><button onclick=\"wanCreateForm()\">Tạo WAN</button></div>`;\n}\nfunction commonWanFields(update=false){\n return `<label>WAN Index</label><input id=\"wi\" type=\"number\" value=\"${update?1:3}\">\n <label>Username</label><input id=\"wu\">\n <label>Password</label><input id=\"wp\" type=\"text\" autocomplete=\"off\">\n <label>VLAN Priority</label><input id=\"vp\" type=\"number\" value=\"${update?2:1}\">\n <label>VLAN Mux ID</label><input id=\"vm\" ty" +
  "pe=\"number\" value=\"${update?11:111}\">\n <label>Addressing Type</label><input id=\"at\" value=\"${update?'':'DHCP'}\">\n <label>Default Gateway</label><select id=\"dg\"><option value=\"1\">${update?'1 - True':'0 - False'}</option><option value=\"0\">${update?'0 - False':'1 - True'}</option></select>`;\n}\nfunction wanDeleteForm(){\n  if(!Array.isArray(wanConfigList) || !wanConfigList.length){\n    $('panel').innerHTML=`<h2>XÓA WAN</h2>\n      <div class=\"status err\">Chưa có dữ liệu WAN. Hãy vào \"Xem cấu hình\" trước.</div>\n      <button onclick=\"viewWan()\">XEM CẤU HÌNH WAN</button>`;\n    return;\n  }\n\n  const options=wanConfigList.map((x,i)=>{\n    const idx=x.wanIndex??i;\n    const name=x.wanName||x.userName||x.connectionType||('WAN #'+(i+1));\n    return `<option value=\"${i}\">WAN ${esc(idx)} - ${esc(name)}</option>`;\n  }).join('');\n\n  $('panel').innerHTML=`<h2>XÓA WAN</h2>\n    <div class=\"status\">Chọn WAN cần xóa. Dữ liệu lấy từ \"Xem cấu hình WAN\", không gọi API getWanConfig thêm.</div>\n    <label>Chọn WAN cần xóa</label>\n    <select id=\"wanDeleteSelect\" onchange=\"fillWanDeleteInfo()\">${options}</select>\n    <div id=\"wanDeleteInfo\"></div>\n    <button class=\"danger\" onclick=\"doWanDelete()\">XÓA WAN ĐANG CHỌN</button>`;\n\n  fillWanDeleteInfo();\n}\n\nfunction fillWanDeleteInfo(){\n  const select=$('wanDeleteSelect');\n  const info=$('wanDeleteInfo');\n  if(!select || !info) return;\n\n  const x=(wanConfigList||[])[Number(select.value)||0];\n  if(!x){\n    info.innerHTML='<div class=\"status err\">Không tìm thấy WAN đang chọn.</div>';\n    return;\n  }\n\n  info.innerHTML=`\n    <div class=\"section-title\">Thông tin WAN sẽ xóa</div>\n    <div class=\"item\">\n      ${row('WAN Index',x.wanIndex)}\n      ${row('WAN Type',x.wanType)}\n      ${row('WAN Name',x.wanName)}\n      ${row('Username',x.userName)}\n      ${row('Con" +
  "nection',x.connectionType)}\n      ${row('Interface',x.wanIfname)}\n      ${row('VLAN',x.vlanMuxID)}\n      ${row('Status',x.connectionStatus)}\n    </div>`;\n}\n\nasync function doWanDelete(){\n  if(!beginAction()) return;\n  try{\n    const selected=Number($('wanDeleteSelect')?.value);\n    const original=(wanConfigList||[])[selected];\n    if(!original) throw new Error('Không tìm thấy WAN đang chọn.');\n\n    const wanIndex=Number(original.wanIndex);\n    const wanType=String(original.wanType??'').trim();\n    if(!Number.isFinite(wanIndex)) throw new Error('WAN Index không hợp lệ.');\n    if(!wanType) throw new Error('WAN Type không hợp lệ.');\n\n    if(!confirm(`Bạn có chắc muốn xóa WAN Index ${wanIndex} (${original.wanName||original.userName||'WAN'})?`))\n      return;\n\n    progressStep('Đang chuẩn bị XÓA WAN...',10);\n    await apiPost({\n      command:'wanDelete',\n      serialNumber:serial,\n      modelName,\n      body:{wanIndex,wanType}\n    });\n\n    progressDone('Xóa WAN thành công');\n    toast('✓ Xóa WAN thành công');\n\n    wanConfigList.splice(selected,1);\n\n    if(wanConfigList.length){\n      wanDeleteForm();\n    }else{\n      $('panel').innerHTML=`<h2>XÓA WAN</h2>\n        <div class=\"status ok\">✓ Đã xóa WAN. Không còn WAN trong dữ liệu đã tải.</div>`;\n    }\n  }catch(e){\n    progressError(e.message);\n    toast(e.message,false);\n  }finally{\n    endAction();\n  }\n}\n\nfunction wanUpdateForm(){\n  if(!Array.isArray(wanConfigList) || !wanConfigList.length){\n    $('panel').innerHTML=`<h2>SỬA WAN</h2>\n      <div class=\"status err\">Chưa có dữ liệu WAN. Hãy vào \"Xem cấu hình\" trước.</div>\n      <button onclick=\"viewWan()\">XEM CẤU HÌNH WAN</button>`;\n    return;\n  }\n\n  const options=wanConfigList.map((x,i)=>{\n    const idx=x.wanIndex??i;\n    const name=x.wanName||x.userName||x.connectionType||('WA" +
  "N #'+(i+1));\n    return `<option value=\"${i}\">WAN ${esc(idx)} - ${esc(name)}</option>`;\n  }).join('');\n\n  $('panel').innerHTML=`<h2>SỬA WAN</h2>\n    <div class=\"status ok\">✓ Dùng dữ liệu đã lấy từ \"Xem cấu hình WAN\" — không gọi getWanConfig lần nữa.</div>\n    <label>Chọn WAN cần sửa</label>\n    <select id=\"wanEditSelect\" onchange=\"fillWanEditForm()\">${options}</select>\n    <div id=\"wanEditFields\"></div>`;\n\n  fillWanEditForm();\n}\n\nconst WAN_MODE_MAP={\n  bridge:{label:'Bridge',wanType:'bridge',connectionType:'PPPoE_Bridged',purpose:'Bridge, đẩy PPPoE ra thiết bị phía sau'},\n  dhcp:{label:'IP Routed / DHCP',wanType:'WANIPConnection',connectionType:'IP_Routed',purpose:'WAN lấy IP bằng DHCP'},\n  pppoe:{label:'PPPoE Routed',wanType:'WANPPPConnection',connectionType:'IP_Routed',purpose:'Modem quay PPPoE'}\n};\n\nfunction wanModeFromApi(wanType,connectionType){\n  if(String(wanType||'').toLowerCase()==='bridge' || String(connectionType||'')==='PPPoE_Bridged') return 'bridge';\n  if(String(wanType||'')==='WANIPConnection') return 'dhcp';\n  return 'pppoe';\n}\n\nfunction wanModeOptions(selected){\n  return Object.entries(WAN_MODE_MAP).map(([key,x])=>\n    `<option value=\"${key}\" ${key===selected?'selected':''}>${x.label}</option>`\n  ).join('');\n}\n\nfunction updateWanModeHint(){\n  const mode=$('wanMode')?.value;\n  const x=WAN_MODE_MAP[mode];\n  if($('wanModeHint') && x){\n    $('wanModeHint').innerHTML='<b>'+esc(x.label)+'</b> — '+esc(x.purpose)+\n      '<br><small>API: '+esc(x.wanType)+' / '+esc(x.connectionType)+'</small>';\n  }\n}\n\nfunction fillWanEditForm(){\n  // Lấy TRỰC TIẾP WAN đã được getWanConfig lưu vào wanConfigList.\n  const list=wanConfigList||[];\n  const select=$('wanEditSelect');\n  const fields=$('wanEditFields');\n  if(!select || !fields) return;\n\n  const x=list[Number(select.value)" +
  "||0];\n  if(!x){\n    fields.innerHTML='<div class=\"status err\">Không tìm thấy cấu hình WAN đã chọn.</div>';\n    return;\n  }\n\n  // Giữ tham chiếu đúng object gốc đã đọc.\n  window.currentWanOriginal=x;\n\n  fields.innerHTML=`\n    <div class=\"section-title\">Cấu hình hiện tại — lấy trực tiếp từ API</div>\n    <div class=\"item\">\n      ${row('WAN Index',x.wanIndex)}\n      ${row('WAN Type',x.wanType)}\n      ${row('Connection',x.connectionType)}\n      ${row('WAN Name',x.wanName)}\n      ${row('Username',x.userName)}\n      ${row('Password',x.password)}\n      ${row('Interface',x.wanIfname)}\n      ${row('Status',x.connectionStatus)}\n      ${row('IPv4',x.externalIPAdress)}\n      ${row('Gateway',x.defaultGateway)}\n      ${row('VLAN Priority',x.vlanPriority)}\n      ${row('VLAN Mux ID',x.vlanMuxID)}\n      ${row('Addressing Type',x.addressingType)}\n      ${row('IPv4 Enable',bool(x.ipv4Enable))}\n      ${row('IPv6 Enable',bool(x.ipv6Enable))}\n      ${row('NAT Enable',bool(x.natEnable))}\n      ${row('Firewall Enable',bool(x.firewallEnable))}\n      ${row('Default Gateway',bool(x.isDefaultGateway))}\n    </div>\n\n    <div class=\"section-title\">Form sửa WAN</div>\n\n    <label>WAN Index</label>\n    <input id=\"wi\" type=\"number\" value=\"${esc(x.wanIndex??'')}\">\n\n    <label>Loại WAN</label>\n    <select id=\"wanMode\" onchange=\"updateWanModeHint()\">\n      ${wanModeOptions(wanModeFromApi(x.wanType,x.connectionType))}\n    </select>\n    <div id=\"wanModeHint\" class=\"status\" style=\"margin-top:8px\"></div>\n\n    <label>WAN Name</label>\n    <input id=\"wn\" value=\"${esc(x.wanName??'')}\">\n\n    <label>Username</label>\n    <input id=\"wu\" value=\"${esc(x.userName??'')}\">\n\n    <label>Password</label>\n    <input id=\"wp\" type=\"text\" autocomplete=\"off\" value=\"${esc(x.password??'')}\" placeholder=\"Mật khẩu (có thể nhìn thấy)\">\n\n" +
  "    <label>VLAN Priority</label>\n    <input id=\"vp\" type=\"number\" value=\"${esc(x.vlanPriority??'')}\">\n\n    <label>VLAN Mux ID</label>\n    <input id=\"vm\" type=\"number\" value=\"${esc(x.vlanMuxID??'')}\">\n\n    <label>Addressing Type</label>\n    <input id=\"at\" value=\"${esc(x.addressingType??'')}\">\n\n    <label>IPv4 Enable</label>\n    <select id=\"i4\">\n      <option value=\"1\" ${x.ipv4Enable===true?'selected':''}>1 - True</option>\n      <option value=\"0\" ${x.ipv4Enable===false?'selected':''}>0 - False</option>\n    </select>\n\n    <label>IPv6 Enable</label>\n    <select id=\"i6\">\n      <option value=\"1\" ${x.ipv6Enable===true?'selected':''}>1 - True</option>\n      <option value=\"0\" ${x.ipv6Enable===false?'selected':''}>0 - False</option>\n    </select>\n\n    <label>NAT Enable</label>\n    <select id=\"nat\">\n      <option value=\"1\" ${x.natEnable===true?'selected':''}>1 - True</option>\n      <option value=\"0\" ${x.natEnable===false?'selected':''}>0 - False</option>\n    </select>\n\n    <label>Firewall Enable</label>\n    <select id=\"fw\">\n      <option value=\"1\" ${x.firewallEnable===true?'selected':''}>1 - True</option>\n      <option value=\"0\" ${x.firewallEnable===false?'selected':''}>0 - False</option>\n    </select>\n\n    <label>Default Gateway</label>\n    <select id=\"dg\">\n      <option value=\"1\" ${x.isDefaultGateway===true?'selected':''}>1 - True</option>\n      <option value=\"0\" ${x.isDefaultGateway===false?'selected':''}>0 - False</option>\n    </select>\n\n    <button class=\"success\" onclick=\"doWanUpdate()\">SỬA WAN</button>`;\n  updateWanModeHint();\n}\n\nasync function doWanUpdate(){\n  if(!beginAction()) return;\n\n  try{\n    const original=window.currentWanOriginal;\n    if(!original) throw new Error('Chưa có cấu hình WAN đã đọc.');\n\n    const wanIndex=numField('wi','WAN Index');\n    const vlanPriori" +
  "ty=numField('vp','VLAN Priority');\n    const vlanMuxID=numField('vm','VLAN Mux ID');\n\n    const mode=$('wanMode')?.value;\n    const selectedMode=WAN_MODE_MAP[mode];\n    if(!selectedMode) throw new Error('Loại WAN không hợp lệ.');\n    const wanType=selectedMode.wanType;\n    const connectionType=selectedMode.connectionType;\n    const wanName=$('wn').value.trim();\n    const userName=$('wu').value.trim();\n    const addressingType=$('at').value.trim();\n\n    if(!wanType) throw new Error('WAN Type không được để trống.');\n    if(!connectionType) throw new Error('Connection Type không được để trống.');\n\n    /*\n      QUAN TRỌNG:\n      Không gửi nguyên object getWanConfig().\n      getWanConfig có nhiều trường chỉ để đọc trạng thái như:\n      interface, connectionStatus, externalIPAdress, gateway...\n      Các trường đó có thể bị API wanUpdate từ chối bằng NOK_INVALID_PARAMETER.\n\n      wanUpdate chỉ gửi các trường thuộc FORM SỬA.\n    */\n    const body={\n      wanIndex,\n      wanType,\n      connectionType,\n      wanName,\n      userName,\n      vlanPriority,\n      vlanMuxID,\n      ipv4Enable:$('i4').value==='1',\n      ipv6Enable:$('i6').value==='1',\n      natEnable:$('nat').value==='1',\n      firewallEnable:$('fw').value==='1',\n      isDefaultGateway:$('dg').value==='1'\n    };\n\n    /*\n      Addressing Type:\n      - Có giá trị -> gửi đúng giá trị người dùng/API đã đọc.\n      - Rỗng -> KHÔNG gửi field, tránh gửi \"\" nếu server không chấp nhận chuỗi rỗng.\n    */\n    if(addressingType!==''){\n      body.addressingType=addressingType;\n    }\n\n    /*\n      Password:\n      - Textbox đang hiển thị password nếu API trả về.\n      - Có password -> gửi password đó.\n      - Không có password -> không tự tạo và không gửi field password.\n    */\n    const password=$('wp').value.trim();\n    if(password!==" +
  "''){\n      body.password=password;\n    }\n\n    const payload={\n      modelName,\n      serialNumber:serial,\n      command:'wanUpdate',\n      body\n    };\n\n    progressStart('Đang SỬA WAN...');\n    progressStep('Đang chuẩn bị payload wanUpdate...',30);\n    progressStep('Đang gửi API wanUpdate...',55);\n\n    await apiPost(payload);\n\n    progressDone('Sửa WAN thành công');\n    toast('✓ Sửa WAN thành công');\n\n    // Cập nhật cache chỉ với các field thực sự đã gửi.\n    Object.assign(original,body);\n    fillWanEditForm();\n\n  }catch(e){\n    progressError(e.message);\n    toast(e.message,false);\n  }finally{\n    endAction();\n  }\n}\n\nfunction wanCreateForm(){\n  $('panel').innerHTML=`\n    <h2>TẠO WAN</h2>\n    <div class=\"section-title\">FORM TẠO WAN</div>\n\n    <label>WAN Index</label>\n    <input id=\"wi\" type=\"number\" value=\"\" min=\"0\">\n\n    <label>Loại WAN</label>\n    <select id=\"wanMode\" onchange=\"updateWanModeHint()\">\n      ${wanModeOptions('pppoe')}\n    </select>\n    <div id=\"wanModeHint\" class=\"status\" style=\"margin-top:8px\"></div>\n\n    <label>WAN Name</label>\n    <input id=\"wn\" value=\"\">\n\n    <label>Username</label>\n    <input id=\"wu\" value=\"\">\n\n    <label>Password</label>\n    <input id=\"wp\" type=\"text\" autocomplete=\"off\" placeholder=\"Nhập mật khẩu (có thể nhìn thấy)\">\n\n    <label>VLAN Priority</label>\n    <input id=\"vp\" type=\"number\" value=\"\" min=\"0\">\n\n    <label>VLAN Mux ID</label>\n    <input id=\"vm\" type=\"number\" value=\"\" min=\"0\">\n\n    <label>Addressing Type</label>\n    <input id=\"at\" value=\"\">\n\n    <label>IPv4 Enable</label>\n    <select id=\"i4\">\n      <option value=\"1\" selected>1 - True</option>\n      <option value=\"0\">0 - False</option>\n    </select>\n\n    <label>IPv6 Enable</label>\n    <select id=\"i6\">\n      <option value=\"1\" selected>1 - True</option>\n      <option value=\"0\">0 " +
  "- False</option>\n    </select>\n\n    <label>NAT Enable</label>\n    <select id=\"nat\">\n      <option value=\"1\" selected>1 - True</option>\n      <option value=\"0\">0 - False</option>\n    </select>\n\n    <label>Firewall Enable</label>\n    <select id=\"fw\">\n      <option value=\"1\">1 - True</option>\n      <option value=\"0\" selected>0 - False</option>\n    </select>\n\n    <label>Default Gateway</label>\n    <select id=\"dg\">\n      <option value=\"1\" selected>1 - True</option>\n      <option value=\"0\">0 - False</option>\n    </select>\n\n    <button class=\"success\" onclick=\"doWanCreate()\">TẠO WAN</button>`;\n  updateWanModeHint();\n}\n\nasync function doWanCreate(){\n  if(!beginAction()) return;\n  try{\n    const wi=numField('wi','WAN Index');\n    const vp=numField('vp','VLAN Priority');\n    const vm=numField('vm','VLAN Mux ID');\n\n    const mode=$('wanMode')?.value;\n    const selectedMode=WAN_MODE_MAP[mode];\n    if(!selectedMode) throw new Error('Loại WAN không hợp lệ.');\n    const wanType=selectedMode.wanType;\n    const connectionType=selectedMode.connectionType;\n    const userName=$('wu').value.trim();\n    const password=$('wp').value;\n    const addressingType=$('at').value.trim();\n\n    if(!wanType) throw new Error('WAN Type không được để trống.');\n    if(!connectionType) throw new Error('Connection Type không được để trống.');\n    if(!userName) throw new Error('Username không được để trống.');\n    if(!password) throw new Error('Password không được để trống.');\n\n    /*\n      TẠO WAN dùng đúng các trường như FORM SỬA WAN.\n      Không hard-code các giá trị của một WAN mẫu.\n    */\n    const payload={\n      modelName,\n      serialNumber:serial,\n      command:'wanCreate',\n      body:{\n        wanType,\n        connectionType,\n        wanName:$('wn').value,\n        userName,\n        password,\n        " +
  "vlanPriority:vp,\n        vlanMuxID:vm,\n        addressingType,\n        ipv4Enable:$('i4').value==='1',\n        ipv6Enable:$('i6').value==='1',\n        natEnable:$('nat').value==='1',\n        firewallEnable:$('fw').value==='1',\n        wanIndex:wi,\n        isDefaultGateway:$('dg').value==='1'\n      }\n    };\n\n    progressStart('Đang TẠO WAN...');\n    progressStep('Đang chuẩn bị payload WAN...',20);\n    progressStep('Đang gửi API wanCreate...',55);\n    await apiPost(payload);\n\n    progressDone('Tạo WAN thành công');\n    toast('✓ Tạo WAN thành công');\n    wanConfigList=[];\n    $('panel').innerHTML=`<h2>TẠO WAN</h2>\n      <div class=\"status ok\">✓ Tạo WAN thành công.</div>\n      <button onclick=\"viewWan()\">XEM LẠI CẤU HÌNH WAN</button>`;\n  }catch(e){\n    progressError(e.message);\n    toast(e.message,false);\n  }finally{\n    endAction();\n  }\n}\n\nasync function viewLan(){\n $('panel').innerHTML='<h2>LAN CONFIG</h2><div class=\"status\">Đang tải...</div>';\n progressStart('Đang lấy cấu hình LAN...');\n try{progressStep('Đang gọi API getLanConfig...',35);const d=await apiGet('/getDeviceConfig',{modelName,serialNumber:serial,command:'getLanConfig'});progressStep('Đang xử lý dữ liệu LAN...',80);const b=d.body||[];\n lanConfigList=Array.isArray(b)?b:[b];\n  let h='<h2>LAN CONFIG</h2>';\n  if(Array.isArray(b))b.forEach((x,i)=>h+=item(`LAN ${x.indexGroup??i}`,Object.entries(x).filter(([k])=>['enable','ipAddress','netMask','indexGroup'].includes(k))));\n  else h+=item('',Object.entries(b));\n  $('panel').innerHTML=h;\n  progressDone('Đã tải LAN');\n }catch(e){progressError(e.message);errorPanel(e)}\n}\nlet lanConfigList=[];\n\nfunction setLan(){\n  if(!Array.isArray(lanConfigList) || !lanConfigList.length){\n    $('panel').innerHTML=`<h2>SET LAN</h2>\n      <div class=\"status err\">Chưa có dữ liệu LAN. Hãy " +
  "vào \"Xem cấu hình\" trước để lấy cấu hình thực tế.</div>\n      <button onclick=\"viewLan()\">XEM CẤU HÌNH LAN</button>`;\n    return;\n  }\n\n  const options=lanConfigList.map((x,i)=>\n    `<option value=\"${i}\">LAN ${esc(x.indexGroup??i)}</option>`\n  ).join('');\n\n  $('panel').innerHTML=`<h2>SET LAN</h2>\n    <div class=\"status ok\">✓ Dùng cấu hình LAN đã đọc từ API.</div>\n    <label>Chọn LAN</label>\n    <select id=\"lanSelect\" onchange=\"fillLanForm()\">${options}</select>\n    <div id=\"lanFields\"></div>`;\n\n  fillLanForm();\n}\n\nfunction fillLanForm(){\n  const select=$('lanSelect');\n  const fields=$('lanFields');\n  if(!select || !fields) return;\n\n  const original=lanConfigList[Number(select.value)||0];\n  if(!original){\n    fields.innerHTML='<div class=\"status err\">Không tìm thấy cấu hình LAN.</div>';\n    return;\n  }\n\n  window.currentLanOriginal=original;\n\n  fields.innerHTML=`\n    <div class=\"section-title\">Cấu hình hiện tại — lấy trực tiếp từ API</div>\n    <div class=\"item\">\n      ${row('Index Group',original.indexGroup)}\n      ${row('Enable',bool(original.enable))}\n      ${row('IP Address',original.ipAddress)}\n      ${row('NetMask',original.netMask)}\n    </div>\n\n    <div class=\"section-title\">Form SET LAN</div>\n    <label>Enable</label>\n    <select id=\"le\">\n      <option value=\"1\" ${original.enable===true?'selected':''}>1 - True</option>\n      <option value=\"0\" ${original.enable===false?'selected':''}>0 - False</option>\n    </select>\n\n    <label>IP Address</label>\n    <input id=\"lip\" value=\"${esc(original.ipAddress??'')}\">\n\n    <label>NetMask</label>\n    <input id=\"lmask\" value=\"${esc(original.netMask??'')}\">\n\n    <label>Index Group</label>\n    <input id=\"lig\" type=\"number\" value=\"${esc(original.indexGroup??'')}\">\n\n    <button class=\"success\" onclick=\"doSetLan()\">SET LAN</button>`;\n}\n" +
  "\nfunction validIPv4(value,label){\n  const s=String(value??'').trim();\n  const p=s.split('.');\n  if(p.length!==4 || p.some(x=>!/^\\d+$/.test(x) || Number(x)>255))\n    throw new Error(`${label} không hợp lệ.`);\n  return s;\n}\n\nasync function doSetLan(){\n  if(!beginAction()) return;\n\n  try{\n    const original=window.currentLanOriginal;\n    if(!original) throw new Error('Chưa có cấu hình LAN đã đọc.');\n\n    const ipAddress=validIPv4($('lip').value,'IP Address');\n    const netMask=validIPv4($('lmask').value,'NetMask');\n    const indexGroup=numField('lig','Index Group');\n\n    const body=JSON.parse(JSON.stringify(original));\n    body.enable=$('le').value==='1';\n    body.ipAddress=ipAddress;\n    body.netMask=netMask;\n    body.indexGroup=indexGroup;\n\n    progressStart('Đang SET LAN...');\n    progressStep('Đang chuẩn bị payload LAN từ cấu hình đã đọc...',25);\n    progressStep('Đang gửi API lanConfig...',55);\n\n    await apiPost({\n      modelName,\n      serialNumber:serial,\n      command:'lanConfig',\n      body\n    });\n\n    Object.assign(original,body);\n\n    progressDone('SET LAN thành công');\n    toast('✓ SET LAN thành công');\n    fillLanForm();\n\n  }catch(e){\n    progressError(e.message);\n    toast(e.message,false);\n  }finally{\n    endAction();\n  }\n}\n\nasync function viewOptical(){\n $('panel').innerHTML='<h2>OPTICAL</h2><div class=\"status\">Đang tải...</div>';\n progressStart('Đang lấy thông số OPTICAL...');\n try{progressStep('Đang gọi API getOpticalInfo...',35);\n   const d=await apiGet('/getOpticalInfo',{modelName,serialNumber:serial});\n   progressStep('Đang phân tích thông số quang...',80);\n   const body=d?.body ?? d;\n\n   // Hiển thị mọi tham số dạng giá trị mà API thực sự trả về,\n   // không đoán tên trường Optical.\n   function opticalRows(value,prefix=''){\n     const rows=[];\n     " +
  "if(value===null || value===undefined) return rows;\n     if(Array.isArray(value)){\n       value.forEach((v,i)=>rows.push(...opticalRows(v,prefix?`${prefix} ${i+1}`:`${i+1}`)));\n     }else if(typeof value==='object'){\n       Object.entries(value).forEach(([k,v])=>{\n         const label=prefix?`${prefix} / ${k}`:k;\n         if(v!==null && typeof v==='object') rows.push(...opticalRows(v,label));\n         else rows.push([label,v]);\n       });\n     }else{\n       rows.push([prefix||'Kết quả',value]);\n     }\n     return rows;\n   }\n\n   const rows=opticalRows(body);\n   $('panel').innerHTML='<h2>OPTICAL</h2>'+\n     (rows.length ? item('',rows) :\n      '<div class=\"status\">API không trả về thông số Optical.</div>');\n   progressDone('Đã tải OPTICAL');\n }catch(e){\n   progressError(e.message);\n   errorPanel(e);\n }\n}\nfunction viewPing(){setPing()}\nfunction setPing(){ $('panel').innerHTML=`<h2>PING DNS</h2><label>Host</label><input id=\"host\" value=\"8.8.8.8\"><button onclick=\"doPing()\">PING</button><div id=\"pingResult\"></div>`}\nasync function doPing(){\n const host=$('host').value.trim()||'8.8.8.8';\n $('pingResult').innerHTML='<div class=\"status\">⏳ Đang thực hiện PING...</div>';\n try{\n   const d=await apiGet('/ping',{modelName,serialNumber:serial,host});\n   const b=d.body??d;\n   let r=typeof b==='object'&&!Array.isArray(b)\n     ?Object.entries(b).filter(([k,v])=>typeof v!=='object')\n     :[];\n   $('pingResult').innerHTML=item('',[['Host',host],...r]);\n   progressDone('PING DNS hoàn tất');\n }catch(e){\n   progressError('PING lỗi: '+e.message);\n   $('pingResult').innerHTML=`<div class=\"status err\">✗ ${esc(e.message)}</div>`;\n }\n}\n\nfunction viewReboot(){setReboot()}\nfunction setReboot(){\n  $('panel').innerHTML=`<h2>REBOOT MODEM</h2>\n  <div class=\"status\">⚠️ Modem sẽ khởi động lại và có thể mất" +
  " kết nối trong một thời gian ngắn.</div>\n  <div class=\"item\">${row('Serial Number',serial)}${row('Model',modelName)}</div>\n  <button class=\"danger\" onclick=\"doReboot()\">⟳ KHỞI ĐỘNG LẠI MODEM</button>`;\n}\nasync function doReboot(){\n  if(!confirm(`Bạn có chắc muốn reboot modem ${serial}?`)) return;\n  if(!beginAction()) return;\n  try{\n    progressStart('Đang reboot modem...');\n    progressStep('Đang chuẩn bị lệnh reboot...',20);\n    await paint();\n    progressStep('Đang gửi POST reboot...',45);\n    await apiPost({command:'reboot',modelName,serialNumber:serial});\n    progressStep('API reboot đã phản hồi...',80);\n    progressDone('Gửi lệnh reboot thành công');\n    toast('✓ Đã gửi lệnh reboot cho modem');\n  }catch(e){\n    progressError('Reboot lỗi: '+e.message);\n    toast('Reboot lỗi: '+e.message,false);\n  }finally{endAction()}\n}\nfunction viewPassword(){noSet('WEB LOGIN PASSWORD - Xem cấu hình')}\nfunction setPassword(){\n  $('panel').innerHTML=`<h2>WEB LOGIN PASSWORD</h2>\n    <div class=\"status\">Username cố định: admin</div>\n    <label>Mật khẩu mới (hiển thị rõ)</label>\n    <input id=\"newpass\" type=\"text\" autocomplete=\"off\">\n    <label>Nhập lại mật khẩu (hiển thị rõ)</label>\n    <input id=\"newpass2\" type=\"text\" autocomplete=\"off\">\n    <button class=\"success\" onclick=\"doSetPassword()\">ĐỔI MẬT KHẨU</button>`;\n}\nasync function doSetPassword(){\n  const password=$('newpass').value;\n  const password2=$('newpass2').value;\n  if(!password){toast('Nhập mật khẩu mới',false);return}\n  if(password!==password2){toast('Hai mật khẩu không giống nhau',false);return}\n  if(!beginAction()) return;\n  try{\n    progressStep('Đang chuẩn bị ĐỔI MẬT KHẨU WEB...',10);\n    await apiPost({serialNumber:serial,modelName,command:'configWebGuiPass',body:{username:'admin',password}});\n    progressDone('Đổi mật" +
  " khẩu thành công');\n    toast('✓ Đổi mật khẩu thành công');\n  }catch(e){\n    progressError(e.message);toast(e.message,false);\n  }finally{endAction()}\n}\n\nasync function viewTopology(){\n  $('panel').innerHTML='<h2>TOPOLOGY</h2><div class=\"status\">Đang tải...</div>';\n  progressStart('Đang lấy TOPOLOGY...');\n\n  try{\n    progressStep('Đang gọi API getTopology...',35);\n\n    const d=await apiGet('/getDeviceConfig',{\n      modelName,\n      serialNumber:serial,\n      command:'getTopology'\n    });\n\n    progressStep('Đang xử lý danh sách thiết bị...',80);\n\n    /*\n      Response thực tế:\n      body = [\n        {\n          ...\n          clientEntryList: [\n            {\n              hostName: \"...\",\n              clientIp: \"...\",\n              clientMac: \"...\"\n            }\n          ]\n        }\n      ]\n\n      Chỉ lấy đúng 3 trường:\n      hostName, clientIp, clientMac.\n    */\n    const nodes=Array.isArray(d?.body) ? d.body : [];\n    const clients=nodes.flatMap(node =>\n      Array.isArray(node?.clientEntryList) ? node.clientEntryList : []\n    );\n\n    let html='<h2>TOPOLOGY</h2>';\n\n    if(!clients.length){\n      html+='<div class=\"status\">Không có thiết bị kết nối.</div>';\n    }else{\n      html+=`<div class=\"status ok\">✓ Có ${clients.length} thiết bị kết nối.</div>`;\n\n      clients.forEach((x,i)=>{\n        html+=item(`CLIENT #${i+1}`,[\n          ['Hostname',x.hostName],\n          ['Client IP',x.clientIp],\n          ['Client MAC',x.clientMac]\n        ]);\n      });\n    }\n\n    $('panel').innerHTML=html;\n    progressDone(`Đã tải TOPOLOGY — ${clients.length} thiết bị`);\n\n  }catch(e){\n    progressError(e.message);\n    errorPanel(e);\n  }\n}\n\nfunction errorPanel(e){$('panel').innerHTML=`<div class=\"status err\">✗ ${esc(e.message)}</div>`}\n</script>\n</body>\n</html>\r\n";

const MIME = {
  '.html':'text/html; charset=utf-8',
  '.js':'application/javascript; charset=utf-8',
  '.css':'text/css; charset=utf-8',
  '.json':'application/json; charset=utf-8',
  '.txt':'text/plain; charset=utf-8',
  '.png':'image/png',
  '.jpg':'image/jpeg',
  '.jpeg':'image/jpeg',
  '.svg':'image/svg+xml',
  '.ico':'image/x-icon'
};

function send(res, status, body, type='application/json; charset=utf-8') {
  res.writeHead(status, {
    'Content-Type': type,
    'Cache-Control': 'no-store'
  });
  res.end(typeof body === 'string' ? body : JSON.stringify(body));
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    let data = '';
    req.on('data', c => {
      data += c;
      if (data.length > 10 * 1024 * 1024) {
        req.destroy();
        reject(new Error('Request body quá lớn'));
      }
    });
    req.on('end', () => resolve(data));
    req.on('error', reject);
  });
}

function requestUpstream(method, targetPath, headers={}, body=null) {
  return new Promise((resolve, reject) => {
    const u = new URL(UPSTREAM + targetPath);
    const h = {
      'Accept': headers.accept || 'application/json',
      'User-Agent': 'Dart/3.10 (dart:io)',
      ...headers,
      'Host': u.host
    };
    delete h.host;
    delete h.Host;

    if (body != null) {
      h['Content-Length'] = Buffer.byteLength(body);
    }

    const req = https.request({
      protocol: u.protocol,
      hostname: u.hostname,
      port: u.port || 443,
      path: u.pathname + u.search,
      method,
      headers: h,
      timeout: 45000
    }, r => {
      let data = '';
      r.setEncoding('utf8');
      r.on('data', c => data += c);
      r.on('end', () => resolve({
        status: r.statusCode || 500,
        headers: r.headers,
        text: data
      }));
    });

    req.on('timeout', () => req.destroy(new Error('Upstream timeout')));
    req.on('error', reject);

    if (body != null) req.write(body);
    req.end();
  });
}

async function proxyJson(req, res, targetPath, extraHeaders={}) {
  try {
    const body = await readBody(req);
    const headers = {
      'content-type': req.headers['content-type'] || 'application/json',
      ...extraHeaders
    };
    const r = await requestUpstream(req.method, targetPath, headers, body || null);
    let parsed;
    try { parsed = JSON.parse(r.text); } catch { parsed = r.text; }
    send(res, r.status, parsed);
  } catch (e) {
    send(res, 502, { error: 'UPSTREAM_ERROR', message: e.message });
  }
}

async function proxyGet(req, res, targetPath, headers={}) {
  try {
    const r = await requestUpstream('GET', targetPath, headers, null);
    let parsed;
    try { parsed = JSON.parse(r.text); } catch { parsed = { errorMessage: r.text }; }
    send(res, r.status, parsed);
  } catch (e) {
    send(res, 502, { error: 'UPSTREAM_ERROR', message: e.message });
  }
}

function modemHeaders() {
  return {
    'accept': 'application/json',
    'content-type': 'application/json',
    'token-key': MODEM_TOKEN_KEY,
    'token-id': MODEM_TOKEN_ID
  };
}

async function routeApi(req, res, url) {
  const p = url.pathname;

  // OneBSS login step 1
  if (p === '/api/auth/step1' && req.method === 'POST') {
    return proxyJson(req, res,
      '/quantri/user/xacthuc_tapdoan_v2',
      {'User-Agent':'Dart/3.10 (dart:io)'});
  }

  // OneBSS OTP/token
  if (p === '/api/auth/step2' && req.method === 'POST') {
    return proxyJson(req, res,
      '/quantri/oauth/token',
      {'User-Agent':'Dart/3.10 (dart:io)'});
  }

  // Login audit log. This replaces google.script.run.nhat_ky().
  if (p === '/api/log-login' && req.method === 'POST') {
    try {
      const raw = await readBody(req);
      const data = JSON.parse(raw || '{}');
      const line = JSON.stringify({
        time: new Date().toISOString(),
        app: data.app || 'MODEM',
        username: data.username || ''
      }) + '\n';
      fs.appendFileSync(path.join(__dirname, 'login_log.jsonl'), line, 'utf8');
      return send(res, 200, {ok:true});
    } catch (e) {
      return send(res, 400, {ok:false, message:e.message});
    }
  }

  // Modem GET:
  // browser: /api/modem/getDeviceInfo?serialNumber=...
  // server:  https://api-onebss.vnpt.vn/esbx/onelink/getDeviceInfo?...
  if (p.startsWith('/api/modem/') && req.method === 'GET') {
    const sub = p.slice('/api/modem'.length);
    const qs = url.search || '';
    return proxyGet(req, res, '/esbx/onelink' + sub + qs, modemHeaders());
  }

  // Modem POST deviceConfig
  if (p === '/api/modem/deviceConfig' && req.method === 'POST') {
    return proxyJson(req, res, '/esbx/onelink/deviceConfig', modemHeaders());
  }

  // Thi công lookup: browser supplies Authorization/app-secret generated by existing JS.
  if (p === '/api/thicong/dsVatTuThiCong' && req.method === 'POST') {
    const auth = req.headers.authorization || '';
    const selected = req.headers.selectedmenuid || '11226';
    const appSecret = req.headers['app-secret'] || '';
    const qs = url.search || '';
    return proxyJson(req, res,
      '/app-thicong/thiCong/traCuuThiCong/dsVatTuThiCong' + qs,
      {
        'accept':'application/json',
        'content-type':'application/json',
        'authorization':auth,
        'selectedmenuid':selected,
        'app-secret':appSecret
      });
  }

  return false;
}

function serveFile(res, file) {
  fs.readFile(file, (err, data) => {
    if (err) return send(res, 404, 'Not found', 'text/plain; charset=utf-8');
    const ext = path.extname(file).toLowerCase();
    res.writeHead(200, {
      'Content-Type': MIME[ext] || 'application/octet-stream',
      'Cache-Control': 'no-store'
    });
    res.end(data);
  });
}

const server = http.createServer(async (req, res) => {
  try {
    const url = new URL(req.url, `http://${req.headers.host || 'localhost'}`);

    if (url.pathname.startsWith('/api/')) {
      const handled = await routeApi(req, res, url);
      if (handled !== false) return;
    }

    if (req.method !== 'GET' && req.method !== 'HEAD') {
      return send(res, 405, {error:'METHOD_NOT_ALLOWED'});
    }

    let filePath;
    if (url.pathname === '/' || url.pathname === '/index.html') {
      return send(res, 200, INDEX_HTML, 'text/html; charset=utf-8');
    } else if (url.pathname === '/main.js') {
      filePath = path.join(__dirname, 'main.js');
    } else {
      const clean = decodeURIComponent(url.pathname).replace(/^\/+/, '');
      // Only serve local files; prevent ../ traversal.
      const candidate = path.resolve(__dirname, clean);
      if (!candidate.startsWith(path.resolve(__dirname) + path.sep)) {
        return send(res, 403, 'Forbidden', 'text/plain; charset=utf-8');
      }
      filePath = candidate;
    }

    serveFile(res, filePath);
  } catch (e) {
    send(res, 500, {error:'SERVER_ERROR', message:e.message});
  }
});

// When embedded by NS_MULTI, launcher.js owns the public HTTP port.
// When run directly, OneLink keeps its original standalone behaviour.
if (!process.env.NS_EMBED) {
  server.listen(PORT, HOST, () => {
    console.log('');
    console.log('==============================================');
    console.log(' OneLink Config Modem - Node.js / Android');
    console.log(` http://${HOST === '0.0.0.0' ? '127.0.0.1' : HOST}:${PORT}`);
    console.log(` LAN: http://<IP-Android>:${PORT}`);
    console.log('==============================================');
  });
}

module.exports = { server };
